// ===== src/core/rng.js =====
// Seeded PRNG (mulberry32). Deterministic per seed — used for future procedural
// content (dimensions, names) and any reproducible randomness.

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Hash a string into a 32-bit integer seed (xfnv1a-ish).
function hashSeed(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

// Convenience: build a generator from a string seed.
function rngFrom(str) {
  return mulberry32(hashSeed(String(str)));
}


// ===== src/core/math.js =====
// Number formatting + small math helpers.
// Scientific notation above 1e6 per design spec; tidy fixed/short forms below.

const SUFFIX = ["", "K", "M", "B", "T", "Qa", "Qi", "Sx", "Sp", "Oc", "No", "Dc"];

function formatNumber(n) {
  if (n === undefined || n === null || Number.isNaN(n)) return "0";
  if (!Number.isFinite(n)) return "Infinity";
  const neg = n < 0;
  n = Math.abs(n);

  let out;
  if (n < 1000) {
    out = n < 10 && n % 1 !== 0 ? n.toFixed(1) : Math.floor(n).toString();
  } else if (n < 1e6) {
    // short suffix form for readability between 1K and 1M
    const tier = Math.floor(Math.log10(n) / 3);
    const scaled = n / Math.pow(1000, tier);
    out = scaled.toFixed(scaled < 100 ? 2 : 0).replace(/\.00$/, "") + SUFFIX[tier];
  } else {
    // scientific above 1e6
    out = n.toExponential(2).replace("e+", "e");
  }
  return neg ? "-" + out : out;
}

// Per-second rate formatting.
function formatRate(n) {
  return formatNumber(n) + "/s";
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

// Smooth approach for animated counters (frame-rate aware).
function approach(current, target, dt, speed = 10) {
  const t = 1 - Math.exp(-speed * dt);
  return current + (target - current) * t;
}


// ===== src/core/tick.js =====
// Fixed-timestep accumulator. Sim runs at a constant TPS regardless of render fps.

const TPS = 10;                 // simulation ticks per second
const TICK_MS = 1000 / TPS;     // ms per sim tick
const TICK_DT = 1 / TPS;        // seconds per sim tick

function createTicker(onTick) {
  let accumulator = 0;
  const MAX_CATCHUP = 200; // safety cap: never run more than 200 sim ticks in one frame

  return function step(frameMs) {
    accumulator += frameMs;
    let ran = 0;
    while (accumulator >= TICK_MS && ran < MAX_CATCHUP) {
      onTick(TICK_DT);
      accumulator -= TICK_MS;
      ran++;
    }
    // discard backlog beyond catch-up cap (e.g. after a long stall)
    if (ran >= MAX_CATCHUP) accumulator = 0;
    return ran;
  };
}


// ===== src/sim/grid.js =====
// Hex grid using axial coordinates (q, r). The playfield is a hexagon of radius
// GRID_RADIUS (radius 3 = 37 cells, spans 7 across the middle row -> "7x7" feel).
// Pointy-top hexes. Six-neighbor adjacency.

const GRID_RADIUS = 5; // radius 5 = 91 cells, spans 11 across (Stage 2 expansion)
const HEX_SIZE = 38; // pixel radius of a hex (center to corner), base zoom

const HEX_DIRS = [
  { q: 1, r: 0 },
  { q: 1, r: -1 },
  { q: 0, r: -1 },
  { q: -1, r: 0 },
  { q: -1, r: 1 },
  { q: 0, r: 1 },
];

function key(q, r) {
  return q + "," + r;
}

// Is (q,r) inside the hexagon playfield?
function inBounds(q, r) {
  const s = -q - r;
  return Math.max(Math.abs(q), Math.abs(r), Math.abs(s)) <= GRID_RADIUS;
}

// All valid cells, ordered for stable iteration.
function allCells() {
  const cells = [];
  for (let q = -GRID_RADIUS; q <= GRID_RADIUS; q++) {
    for (let r = -GRID_RADIUS; r <= GRID_RADIUS; r++) {
      if (inBounds(q, r)) cells.push({ q, r });
    }
  }
  return cells;
}

// Hex (axial) distance between two cells.
function hexDistance(aq, ar, bq, br) {
  return (Math.abs(aq - bq) + Math.abs(ar - br) + Math.abs(aq + ar - bq - br)) / 2;
}

function neighbors(q, r) {
  const out = [];
  for (const d of HEX_DIRS) {
    const nq = q + d.q;
    const nr = r + d.r;
    if (inBounds(nq, nr)) out.push({ q: nq, r: nr });
  }
  return out;
}

// Axial -> pixel (pointy-top). Returns offset from grid origin (0,0 axial).
function axialToPixel(q, r, size = HEX_SIZE) {
  const x = size * Math.sqrt(3) * (q + r / 2);
  const y = size * 1.5 * r;
  return { x, y };
}

// Pixel -> nearest axial cell (pointy-top), with cube rounding.
function pixelToAxial(x, y, size = HEX_SIZE) {
  const q = ((Math.sqrt(3) / 3) * x - (1 / 3) * y) / size;
  const r = ((2 / 3) * y) / size;
  return cubeRound(q, r);
}

function cubeRound(q, r) {
  let x = q;
  let z = r;
  let y = -x - z;
  let rx = Math.round(x);
  let ry = Math.round(y);
  let rz = Math.round(z);
  const dx = Math.abs(rx - x);
  const dy = Math.abs(ry - y);
  const dz = Math.abs(rz - z);
  if (dx > dy && dx > dz) rx = -ry - rz;
  else if (dy > dz) ry = -rx - rz;
  else rz = -rx - ry;
  return { q: rx, r: rz };
}

// Corner points of a pointy-top hex centered at (cx, cy).
function hexCorners(cx, cy, size = HEX_SIZE) {
  const pts = [];
  for (let i = 0; i < 6; i++) {
    const ang = (Math.PI / 180) * (60 * i - 30);
    pts.push({ x: cx + size * Math.cos(ang), y: cy + size * Math.sin(ang) });
  }
  return pts;
}


